selector_to_html = {"a[href=\"#pyskyfire.ducts.orifice.Orifice._result\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.orifice.Orifice._result\">\n<span class=\"sig-name descname\"><span class=\"pre\">_result</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">eos</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">inlet</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">p_throat</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">p_out</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">choked</span></span></em><span class=\"sig-paren\">)</span></dt><dd></dd>", "a[href=\"#pyskyfire.ducts.orifice.Orifice.length_to_diameter\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.orifice.Orifice.length_to_diameter\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">property</span></span><span class=\"w\"> </span></span><span class=\"sig-name descname\"><span class=\"pre\">length_to_diameter</span></span><span class=\"property\"><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a></span></dt><dd><p>Passage length over hydraulic diameter, <code class=\"docutils literal notranslate\"><span class=\"pre\">L/D</span></code>. NaN without a diameter.</p></dd>", "a[href=\"#pyskyfire.ducts.orifice.Orifice.annular\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.orifice.Orifice.annular\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">classmethod</span></span><span class=\"w\"> </span></span><span class=\"sig-name descname\"><span class=\"pre\">annular</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">inner_diameter</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">outer_diameter</span></span></em>, <em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">cd</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">length</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">0.0</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>The annulus between two concentric diameters [m], as around a coaxial post.</p></dd>", "a[href=\"#pyskyfire-ducts-orifice-orifice\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.ducts.orifice.Orifice<a class=\"headerlink\" href=\"#pyskyfire-ducts-orifice-orifice\" title=\"Link to this heading\">\u00b6</a></h1>", "a[href=\"#pyskyfire.ducts.orifice.Orifice.effective_area\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.orifice.Orifice.effective_area\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">property</span></span><span class=\"w\"> </span></span><span class=\"sig-name descname\"><span class=\"pre\">effective_area</span></span><span class=\"property\"><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a></span></dt><dd><p>Discharge coefficient times area, <code class=\"docutils literal notranslate\"><span class=\"pre\">Cd\u00b7A</span></code> [m\u00b2].</p></dd>", "a[href=\"#pyskyfire.ducts.orifice.Orifice.__repr__\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.orifice.Orifice.__repr__\">\n<span class=\"sig-name descname\"><span class=\"pre\">__repr__</span></span><span class=\"sig-paren\">(</span><span class=\"sig-paren\">)</span></dt><dd></dd>", "a[href=\"#pyskyfire.ducts.orifice.Orifice.solve\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.orifice.Orifice.solve\">\n<span class=\"sig-name descname\"><span class=\"pre\">solve</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">inlet_state</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference internal\" href=\"../../thermo/state/FluidState.html#pyskyfire.thermo.state.FluidState\" title=\"pyskyfire.thermo.state.FluidState\"><span class=\"pre\">FluidState</span></a></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">mass_flow</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">fluid</span></span></em><span class=\"sig-paren\">)</span> <span class=\"sig-return\"><span class=\"sig-return-icon\">\u2192</span> <span class=\"sig-return-typehint\"><a class=\"reference internal\" href=\"OrificeResult.html#pyskyfire.ducts.orifice.OrificeResult\" title=\"pyskyfire.ducts.orifice.OrificeResult\"><span class=\"pre\">OrificeResult</span></a></span></span></dt><dd><p>The discharge pressure that drives <code class=\"docutils literal notranslate\"><span class=\"pre\">mass_flow</span></code> through the orifice.</p></dd>", "a[href=\"#pyskyfire.ducts.orifice.Orifice.sized\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.orifice.Orifice.sized\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">classmethod</span></span><span class=\"w\"> </span></span><span class=\"sig-name descname\"><span class=\"pre\">sized</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">mass_flow</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">inlet_state</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">dp</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">fluid</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">cd</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">length</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">0.0</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>The round hole that passes <code class=\"docutils literal notranslate\"><span class=\"pre\">mass_flow</span></code> with a pressure drop <code class=\"docutils literal notranslate\"><span class=\"pre\">dp</span></code>.</p><p>See <code class=\"xref py py-func docutils literal notranslate\"><span class=\"pre\">required_area()</span></code>.</p></dd>", "a[href=\"../../thermo/eos/index.html#pyskyfire.thermo.eos.as_equation_of_state\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.thermo.eos.as_equation_of_state\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.thermo.eos.</span></span><span class=\"sig-name descname\"><span class=\"pre\">as_equation_of_state</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">fluid</span></span></em><span class=\"sig-paren\">)</span> <span class=\"sig-return\"><span class=\"sig-return-icon\">\u2192</span> <span class=\"sig-return-typehint\"><a class=\"reference internal\" href=\"../../thermo/eos/EquationOfState.html#pyskyfire.thermo.eos.EquationOfState\" title=\"pyskyfire.thermo.eos.EquationOfState\"><span class=\"pre\">EquationOfState</span></a></span></span></dt><dd><p>Read <code class=\"docutils literal notranslate\"><span class=\"pre\">fluid</span></code> as an equation of state.</p><p>An <a class=\"reference internal\" href=\"../../thermo/eos/EquationOfState.html#pyskyfire.thermo.eos.EquationOfState\" title=\"pyskyfire.thermo.eos.EquationOfState\"><code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">EquationOfState</span></code></a> is returned as it is. Anything else names a\nCoolProp fluid and is handed to <a class=\"reference internal\" href=\"../../thermo/eos/CoolPropEOS.html#pyskyfire.thermo.eos.CoolPropEOS\" title=\"pyskyfire.thermo.eos.CoolPropEOS\"><code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">CoolPropEOS</span></code></a>.</p></dd>", "a[href=\"../../thermo/eos/Incompressible.html#pyskyfire.thermo.eos.Incompressible\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.thermo.eos.Incompressible\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.thermo.eos.</span></span><span class=\"sig-name descname\"><span class=\"pre\">Incompressible</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">rho</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">cp</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">|</span></span><span class=\"w\"> </span><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/constants.html#None\" title=\"(in Python v3.15)\"><span class=\"pre\">None</span></a></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">None</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Bases: <code class=\"xref py py-obj docutils literal notranslate\"><span class=\"pre\">EquationOfState</span></code></p><p>A fluid of constant density.</p><p>Enthalpy is <code class=\"docutils literal notranslate\"><span class=\"pre\">cp*T</span> <span class=\"pre\">+</span> <span class=\"pre\">p/rho</span></code>. With constant density, an isentropic\nprocess is also isothermal, so it moves only the <code class=\"docutils literal notranslate\"><span class=\"pre\">p/rho</span></code> term. The\nisentropic head between two pressures is then <code class=\"docutils literal notranslate\"><span class=\"pre\">\u0394p/rho</span></code> exactly: the\nfamiliar pump head.</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">cp</span></code> is optional. Without it temperature is carried through isentropic\nprocesses but cannot be recovered from an enthalpy, so <a class=\"reference internal\" href=\"#pyskyfire.thermo.eos.Incompressible.state_ph\" title=\"pyskyfire.thermo.eos.Incompressible.state_ph\"><code class=\"xref py py-meth docutils literal notranslate\"><span class=\"pre\">state_ph()</span></code></a>\nreports it as NaN, and there is no entropy: <a class=\"reference internal\" href=\"#pyskyfire.thermo.eos.Incompressible.entropy\" title=\"pyskyfire.thermo.eos.Incompressible.entropy\"><code class=\"xref py py-meth docutils literal notranslate\"><span class=\"pre\">entropy()</span></code></a> and\n<a class=\"reference internal\" href=\"#pyskyfire.thermo.eos.Incompressible.state_hs\" title=\"pyskyfire.thermo.eos.Incompressible.state_hs\"><code class=\"xref py py-meth docutils literal notranslate\"><span class=\"pre\">state_hs()</span></code></a> need <code class=\"docutils literal notranslate\"><span class=\"pre\">cp</span></code>. Entropy is then <code class=\"docutils literal notranslate\"><span class=\"pre\">cp*ln(T)</span></code>, datum 1 K.\nSound is infinitely fast in an incompressible fluid.</p></dd>", "a[href=\"OrificeResult.html#pyskyfire.ducts.orifice.OrificeResult\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.orifice.OrificeResult\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.ducts.orifice.</span></span><span class=\"sig-name descname\"><span class=\"pre\">OrificeResult</span></span></dt><dd><p>States and diagnostics of the flow through an orifice.</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">throat_state</span></code> is the ideal isentropic state at the vena contracta and\n<code class=\"docutils literal notranslate\"><span class=\"pre\">velocity</span></code> the ideal jet velocity there [m/s]. The real jet is slower by\nthe velocity coefficient, which the discharge coefficient includes but\ndoes not separate out. <code class=\"docutils literal notranslate\"><span class=\"pre\">outlet_state</span></code> is at the discharge pressure with\nthe inlet enthalpy: the jet\u2019s kinetic energy has been dissipated.\n<code class=\"docutils literal notranslate\"><span class=\"pre\">choked</span></code> is True when the discharge pressure lies below the pressure at\nwhich the ideal mass flux peaks, so lowering it further adds no flow.</p></dd>", "a[href=\"#pyskyfire.ducts.orifice.Orifice.solve_inlet_pressure\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.orifice.Orifice.solve_inlet_pressure\">\n<span class=\"sig-name descname\"><span class=\"pre\">solve_inlet_pressure</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">mass_flow</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">p_out</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">T_in</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">fluid</span></span></em><span class=\"sig-paren\">)</span> <span class=\"sig-return\"><span class=\"sig-return-icon\">\u2192</span> <span class=\"sig-return-typehint\"><a class=\"reference internal\" href=\"OrificeResult.html#pyskyfire.ducts.orifice.OrificeResult\" title=\"pyskyfire.ducts.orifice.OrificeResult\"><span class=\"pre\">OrificeResult</span></a></span></span></dt><dd><p>The inlet pressure that drives <code class=\"docutils literal notranslate\"><span class=\"pre\">mass_flow</span></code> to a discharge at <code class=\"docutils literal notranslate\"><span class=\"pre\">p_out</span></code>.</p><p>The inlet is at temperature <code class=\"docutils literal notranslate\"><span class=\"pre\">T_in</span></code> [K], and its state is resolved\nfrom that and each trial pressure. This is the question a feed\nplenum asks: what it must hold to deliver a flow into a chamber at\nknown pressure. Parameters are otherwise as for <a class=\"reference internal\" href=\"#pyskyfire.ducts.orifice.Orifice.solve\" title=\"pyskyfire.ducts.orifice.Orifice.solve\"><code class=\"xref py py-meth docutils literal notranslate\"><span class=\"pre\">solve()</span></code></a>.</p></dd>", "a[href=\"../../thermo/state/FluidState.html#pyskyfire.thermo.state.FluidState\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.thermo.state.FluidState\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.thermo.state.</span></span><span class=\"sig-name descname\"><span class=\"pre\">FluidState</span></span></dt><dd><p>Resolved bulk fluid state at one axial station.</p></dd>", "a[href=\"#pyskyfire.ducts.orifice.Orifice.mass_flow\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.orifice.Orifice.mass_flow\">\n<span class=\"sig-name descname\"><span class=\"pre\">mass_flow</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">inlet_state</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference internal\" href=\"../../thermo/state/FluidState.html#pyskyfire.thermo.state.FluidState\" title=\"pyskyfire.thermo.state.FluidState\"><span class=\"pre\">FluidState</span></a></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">p_out</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">fluid</span></span></em><span class=\"sig-paren\">)</span> <span class=\"sig-return\"><span class=\"sig-return-icon\">\u2192</span> <span class=\"sig-return-typehint\"><a class=\"reference internal\" href=\"OrificeResult.html#pyskyfire.ducts.orifice.OrificeResult\" title=\"pyskyfire.ducts.orifice.OrificeResult\"><span class=\"pre\">OrificeResult</span></a></span></span></dt><dd><p>The flow the orifice passes from <code class=\"docutils literal notranslate\"><span class=\"pre\">inlet_state</span></code> to a discharge pressure.</p><p>Parameters are as for <a class=\"reference internal\" href=\"#pyskyfire.ducts.orifice.Orifice.solve\" title=\"pyskyfire.ducts.orifice.Orifice.solve\"><code class=\"xref py py-meth docutils literal notranslate\"><span class=\"pre\">solve()</span></code></a>, with <code class=\"docutils literal notranslate\"><span class=\"pre\">p_out</span></code> the discharge\npressure [Pa] instead of a mass flow. Below the choking pressure the\nflow no longer depends on <code class=\"docutils literal notranslate\"><span class=\"pre\">p_out</span></code>, and the result says so.</p></dd>", "a[href=\"#pyskyfire.ducts.orifice.Orifice\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.orifice.Orifice\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.ducts.orifice.</span></span><span class=\"sig-name descname\"><span class=\"pre\">Orifice</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">area</span></span></em>, <em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">cd</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">hydraulic_diameter</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">length</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">0.0</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>A short restriction discharging into a large volume.</p><p class=\"rubric\">Notes</p><p>Use <a class=\"reference internal\" href=\"#pyskyfire.ducts.orifice.Orifice.circular\" title=\"pyskyfire.ducts.orifice.Orifice.circular\"><code class=\"xref py py-meth docutils literal notranslate\"><span class=\"pre\">circular()</span></code></a>, <a class=\"reference internal\" href=\"#pyskyfire.ducts.orifice.Orifice.annular\" title=\"pyskyfire.ducts.orifice.Orifice.annular\"><code class=\"xref py py-meth docutils literal notranslate\"><span class=\"pre\">annular()</span></code></a> or <a class=\"reference internal\" href=\"#pyskyfire.ducts.orifice.Orifice.slot\" title=\"pyskyfire.ducts.orifice.Orifice.slot\"><code class=\"xref py py-meth docutils literal notranslate\"><span class=\"pre\">slot()</span></code></a> for those shapes.\nThe generic constructor takes any area, so an effective area quoted as\n<code class=\"docutils literal notranslate\"><span class=\"pre\">Cd\u00b7A</span></code> can be given as <code class=\"docutils literal notranslate\"><span class=\"pre\">Orifice(area=CdA,</span> <span class=\"pre\">cd=1.0)</span></code>.</p></dd>", "a[href=\"#pyskyfire.ducts.orifice.Orifice.circular\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.orifice.Orifice.circular\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">classmethod</span></span><span class=\"w\"> </span></span><span class=\"sig-name descname\"><span class=\"pre\">circular</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">diameter</span></span></em>, <em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">cd</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">length</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">0.0</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>A round hole of <code class=\"docutils literal notranslate\"><span class=\"pre\">diameter</span></code> [m].</p></dd>", "a[href=\"#pyskyfire.ducts.orifice.Orifice.slot\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.orifice.Orifice.slot\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">classmethod</span></span><span class=\"w\"> </span></span><span class=\"sig-name descname\"><span class=\"pre\">slot</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">width</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">height</span></span></em>, <em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">cd</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">length</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">0.0</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>A rectangular slot of <code class=\"docutils literal notranslate\"><span class=\"pre\">width</span></code> by <code class=\"docutils literal notranslate\"><span class=\"pre\">height</span></code> [m].</p></dd>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 600, interactive: false,
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
